    /// <summary>输出内联 SVG；未知名称返回空串（页面不炸，只是没图标）。返回 HtmlString 防 Razor 转义。</summary>
    public static HtmlString Svg(string name, int size = 20, string? cls = null)
    {
        if (!Paths.TryGetValue(name, out var inner)) return new HtmlString("");
        var classAttr = string.IsNullOrEmpty(cls) ? "" : $" class=\"{cls}\"";
        return new HtmlString($"<svg{classAttr} xmlns=\"http://www.w3.org/2000/svg\" width=\"{size}\" height=\"{size}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">{inner}</svg>");
    }
